using System.Diagnostics;
using System.Runtime.CompilerServices;
using TextAnalysis;

// Prevent dead-code elimination
static T Consume<T>(T value) { Volatile.Read(ref Unsafe.AsRef(ref Unsafe.As<T, byte>(ref value))); return value; }

const int WarmupIterations = 500;
const int MeasureIterations = 5000;

var smallAnalyzer = new TextAnalyzer("The quick brown fox jumps over the lazy dog");

// ~1000 words
var rng = new Random(42);
var words = new string[1000];
for (int i = 0; i < words.Length; i++)
{
    int len = rng.Next(2, 12);
    var chars = new char[len];
    for (int j = 0; j < len; j++)
        chars[j] = (char)('a' + rng.Next(0, 26));
    words[i] = new string(chars);
}
var largeAnalyzer = new TextAnalyzer(string.Join(' ', words));

Console.WriteLine($"Runtime: {System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription}");
Console.WriteLine($"Warmup: {WarmupIterations}, Measure: {MeasureIterations} iterations");
Console.WriteLine($"{"Method",-35} {"Mean (ns)",>12} {"StdDev (ns)",>12}");
Console.WriteLine(new string('-', 62));

RunBenchmark("AverageWordLength_Small", () => Consume(smallAnalyzer.AverageWordLength()));
RunBenchmark("AverageWordLength_Large", () => Consume(largeAnalyzer.AverageWordLength()));
RunBenchmark("WordLengthHistogram_Small", () => Consume(smallAnalyzer.WordLengthHistogram()));
RunBenchmark("WordLengthHistogram_Large", () => Consume(largeAnalyzer.WordLengthHistogram()));
RunBenchmark("UniqueWordCount_Small", () => Consume(smallAnalyzer.UniqueWordCount()));
RunBenchmark("UniqueWordCount_Large", () => Consume(largeAnalyzer.UniqueWordCount()));

static void RunBenchmark(string name, Action action)
{
    // Warmup
    for (int i = 0; i < WarmupIterations; i++) action();

    // Collect per-batch timings (batches of 100 to reduce stopwatch overhead)
    const int batchSize = 100;
    int batches = MeasureIterations / batchSize;
    double[] batchNs = new double[batches];
    var sw = new Stopwatch();

    for (int b = 0; b < batches; b++)
    {
        sw.Restart();
        for (int i = 0; i < batchSize; i++) action();
        sw.Stop();
        batchNs[b] = sw.Elapsed.TotalNanoseconds / batchSize;
    }

    double mean = batchNs.Average();
    double stddev = Math.Sqrt(batchNs.Select(x => (x - mean) * (x - mean)).Average());
    Console.WriteLine($"{name,-35} {mean,12:F1} {stddev,12:F1}");
}

